INSERT INTO `announcements` (`id`, `title`, `content`, `target_role`, `class_id`, `author_id`, `created_at`, `updated_at`) VALUES
(2, 'Selamat Datang di SIAKAD SD Al-Ukhuwah', 'Kami senang menyambut Anda di Sistem Informasi Akademik (SIAKAD) baru kami. Gunakan platform ini untuk memantau nilai, kehadiran, dan informasi penting lainnya.', 'all', NULL, 1, '2026-02-21 16:22:58', '2026-02-21 16:22:58'),
(3, 'Rapat Kerja Guru Semester Ganjil', 'Diberitahukan kepada seluruh Bapak/Ibu Guru bahwa rapat koordinasi persiapan semester ganjil akan dilaksanakan pada hari Senin depan pukul 09:00 WIB.', 'teacher', NULL, 1, '2026-02-21 16:22:58', '2026-02-21 16:22:58'),
(4, 'Pengingat Pembayaran Iuran Sekolah', 'Mohon kerjasamanya kepada seluruh Orang Tua murid untuk menyelesaikan administrasi sebelum pekan ujian dilaksanakan.', 'all', NULL, 1, '2026-02-21 16:22:58', '2026-02-21 16:22:58'),
(5, 'Jadwal Ekstrakurikuler Pramuka', 'Kegiatan Pramuka untuk kelas 3-6 akan dilaksanakan setiap hari Sabtu mulai pukul 08:00 WIB. Mohon membawa perlengkapan lengkap.', 'student', NULL, 1, '2026-02-21 16:22:58', '2026-02-21 16:22:58'),
(6, 'Info Penting Kelas Kelas 1A', 'Ada pembaruan mengenai proyek kelas untuk siswa Kelas 1A. Silakan cek menu Tugas untuk detail lebih lanjut.', 'student', 1, 1, '2026-02-21 16:22:58', '2026-02-21 16:22:58'),
(7, 'Info Penting Kelas Kelas 1B', 'Ada pembaruan mengenai proyek kelas untuk siswa Kelas 1B. Silakan cek menu Tugas untuk detail lebih lanjut.', 'student', 2, 1, '2026-02-21 16:22:58', '2026-02-21 16:22:58');
